// とっくんの島 — a special stage of classic counting problems (dice, coin tables, league/tournament, elections).
// Each make() is checked in tests/verify_worlds.mjs against independent brute-force counters over many parameter sets.
const DR = {
  D: [1, 2, 3, 4, 5, 6],
  conds: {
    sumEq: (v) => (a, b) => a + b === v, sumGe: (v) => (a, b) => a + b >= v, prodEq: (v) => (a, b) => a * b === v,
    prodMult: (m) => (a, b) => (a * b) % m === 0, div: () => (a, b) => a % b === 0, // a = big die, b = small die
  },
  dice2: (pred) => { let c = 0; for (const a of DR.D) for (const b of DR.D) if (pred(a, b)) c++; return c; },
  // nondecreasing triples (the 組) satisfying pred, and how many orders each has
  parts3: (pred) => { const out = []; for (let a = 1; a <= 6; a++) for (let b = a; b <= 6; b++) for (let c = b; c <= 6; c++) if (pred(a + b + c)) out.push([a, b, c]); return out; },
  arr3: ([a, b, c]) => (a === b && b === c ? 1 : a === b || b === c ? 3 : 6),
  // all ways to pay `tot` with denominations, per-coin min/max and optional total-coin cap
  pay: (den, tot, mins, maxs, cap) => { const out = []; const go = (i, left, cur) => { if (i === den.length) { if (left === 0 && (cap === undefined || cur.reduce((a, b) => a + b, 0) <= cap)) out.push([...cur]); return; }
    for (let k = mins[i]; k <= Math.min(maxs[i], Math.floor(left / den[i])); k++) { cur.push(k); go(i + 1, left - k * den[i], cur); cur.pop(); } }; go(0, tot, []); return out; },
  amounts: (coins) => { let s = new Set([0]); for (const [v, c] of coins) { const n = new Set(); for (const x of s) for (let k = 0; k <= c; k++) n.add(x + v * k); s = n; } s.delete(0); return s.size; },
  league: (n) => n * (n - 1) / 2, tour: (n) => n - 1,
  rounds: (n) => Math.ceil(Math.log2(n)),
};
