  big: tx('大', 'big', '大'), small: tx('小', 'small', '小'), done: tx('けってい', 'Done', '确定'), picked: tx('えらんだマス: {k}', 'Squares picked: {k}', '已选：{k}'),
  extra: tx('条件に合わないマスが入っているよ(赤いマス)。', 'Some squares don’t fit the rule (shown in red).', '有不符合条件的格子（红色）。'),
  missing: tx('まだ {k} マス足りないよ。行ごとに、左から順に見ていこう。', '{k} squares still missing. Go row by row, left to right.', '还少 {k} 格。一行一行、从左到右看。'),
  addPart: tx('この組を追加', 'Add this group', '添加这一组'), allFound: tx('ぜんぶ見つけた', 'That’s all of them', '都找到了'),
  partNo: tx('その組は条件に合わないよ(和は {s})。', 'That group doesn’t fit (its sum is {s}).', '这一组不符合条件（和是 {s}）。'), partDup: tx('その組はもう見つけたよ。', 'You already have that group.', '这一组已经找到了。'),
  partMiss: tx('組がまだ {k} つ足りないよ。いちばん小さい数を1, 2, 3…と決めて、もれなく探そう。', '{k} more group(s) to find. Fix the smallest number as 1, 2, 3 … and search in order.', '还差 {k} 组。把最小的数依次定为1、2、3……按顺序找，不遗漏。'),
  step2: tx('つぎは、それぞれの組が 3つのサイコロに 何通りの ならび方で出るか えらぼう。', 'Now choose how many ways each group can land on the three dice.', '接下来，选每一组在三颗骰子上有几种出法。'),
  arr1: tx('1通り(ぜんぶ同じ)', '1 way (all the same)', '1种（全都一样）'), arr3: tx('3通り(ちがう1つがどこか ₃C₁)', '3 ways (where the odd one goes, ₃C₁)', '3种（不同的那个放哪 ₃C₁）'), arr6: tx('6通り(3×2×1)', '6 ways (3×2×1)', '6种（3×2×1）'),
  check: tx('たしかめる', 'Check', '检查'),
  arrWrong: tx('ならび方がちがう組があるよ。ぜんぶ同じ→1、2つ同じ→ちがう1つがどの位置か ₃C₁=3、ぜんぶちがう→3×2×1=6。', 'Some group has the wrong count. All same → 1; two the same → where the odd one sits, ₃C₁ = 3; all different → 3×2×1 = 6.', '有的组出法不对。全一样→1；两个一样→不同的那个放哪 ₃C₁=3；全不同→3×2×1=6。'),
