  rowAsk: tx('この行は何通り? (タップして入れよう。できないときは 0)', 'How many ways in this row? (tap it; 0 if impossible)', '这一行有几种？（点一下填，凑不出来就填0）'),
  rowWrong: tx('この行をもう一度。のこりの金がくを、のこりのお金で何通りに分けられる? 枚数の上限にも注意。', 'Check this row again: how many ways can the rest be made with the remaining coins? Mind the coin limits.', '再看这一行：剩下的钱用剩下的硬币有几种凑法？注意枚数上限。'),
  rowsDone: tx('行がぜんぶうまったね! 合計は?', 'All rows done! What’s the total?', '每行都填好了！合计是多少？'),
  yen: tx('{v}円', '{v} yen', '{v}日元'), coinsN: tx('{c}円が{k}まい', '{k} × {c}-yen', '{c}日元{k}枚'), rest: tx('のこり {r}円', 'rest {r} yen', '剩下 {r} 日元'),
  votes: tx('票', 'votes', '票'), games: tx('試合', 'games', '场'), kind: tx('通り', 'ways', '种'), sheets: tx('まい', 'coins', '枚'),
