function diceGridTask(pred) {
  return (box, api) => { const st = api.state; if (!st.on) st.on = new Set(); const on = st.on; let bad = new Set();
    const want = new Set(); for (const a of DR.D) for (const b of DR.D) if (pred(a, b)) want.add(a + ',' + b);
    const draw = () => { let t = `<table class="qtable" style="max-width:380px"><tr><th style="font-size:.75rem">${T(DRT.small)}＼${T(DRT.big)}</th>${DR.D.map((a) => `<th>${a}</th>`).join('')}</tr>`;
      for (const b of DR.D) t += `<tr><th>${b}</th>${DR.D.map((a) => { const k = a + ',' + b; return `<td data-cell="${k}" style="cursor:pointer;background:${bad.has(k) ? '#ffd0d8' : on.has(k) ? '#ffc94d' : 'var(--paper2)'};font-weight:800;min-width:38px;height:36px">${on.has(k) ? '●' : ''}</td>`; }).join('')}</tr>`;
      box.innerHTML = `<div class="panel interact"><div class="tw">${t}</table></div><div class="disp" style="font-size:1.1rem">${T(DRT.picked, { k: on.size })}</div><button class="btn" id="dn" type="button">${T(DRT.done)}</button></div>`;
      $$('[data-cell]', box).forEach((c) => c.onclick = () => { const k = c.dataset.cell; on.has(k) ? on.delete(k) : on.add(k); bad = new Set(); snd('pop'); draw(); });
      $('#dn', box).onclick = () => { bad = new Set([...on].filter((k) => !want.has(k))); if (bad.size) { api.bad(T(DRT.extra), 'drillGrid'); draw(); return; }
        if (on.size < want.size) { api.bad(T(DRT.missing, { k: want.size - on.size }), 'drillGrid'); return; } api.ok(); }; };
    draw(); };
}
function partTask(pred) {
  return (box, api) => { const st = api.state; if (!st.found) { st.found = []; st.stage = 1; st.arr = {}; st.cur = [1, 1, 1]; }
    const want = DR.parts3(pred).map((t) => t.join(','));
    const draw = (msg) => { const rowH = st.found.map((k) => { const t = k.split(',').map(Number);
        return `<tr><td style="font-family:var(--f-display);font-size:1.15rem">(${t.join(', ')})</td>${st.stage >= 2 ? `<td>${[1, 3, 6].map((n) => `<button class="chip ${st.arr[k] === n ? 'on' : ''}" data-arr="${k}|${n}" type="button" ${st.stage > 2 ? 'disabled' : ''}>${T(DRT['arr' + n])}</button>`).join(' ')}</td>` : ''}</tr>`; }).join('');
      box.innerHTML = `<div class="panel interact">${st.stage === 1 ? `<div class="row" style="justify-content:center">${[0, 1, 2].map((i) => `<div class="stepper"><button data-dv="${i}|-1" type="button" aria-label="minus">−</button><span class="v">${st.cur[i]}</span><button data-dv="${i}|1" type="button" aria-label="plus">＋</button></div>`).join('')}</div>
        <div class="row" style="justify-content:center"><button class="btn ghost" id="addp" type="button">${T(DRT.addPart)}</button><button class="btn" id="allp" type="button">${T(DRT.allFound)}</button></div>` : st.stage === 2 ? `<div class="tdesc">${T(DRT.step2)}</div>` : ''}
        <div class="tw"><table class="qtable">${rowH}</table></div>${st.stage === 2 ? `<button class="btn" id="chk" type="button">${T(DRT.check)}</button>` : ''}${st.stage === 3 ? `<div class="tdesc">${T(DRT.total)}</div><div id="np" style="width:100%"></div>` : ''}${msg ? `<div class="tdesc">${msg}</div>` : ''}</div>`;
      $$('[data-dv]', box).forEach((b) => b.onclick = () => { const [i, d] = b.dataset.dv.split('|').map(Number); st.cur[i] = Math.min(6, Math.max(1, st.cur[i] + d)); draw(); });
      const ap = $('#addp', box); if (ap) ap.onclick = () => { const t = [...st.cur].sort((a, b) => a - b), k = t.join(','), s = t[0] + t[1] + t[2];
        if (!pred(s)) { draw(T(DRT.partNo, { s })); return; } if (st.found.includes(k)) { draw(T(DRT.partDup)); return; } st.found.push(k); st.found.sort(); snd('pop'); draw(); };
      const al = $('#allp', box); if (al) al.onclick = () => { const miss = want.filter((k) => !st.found.includes(k)).length; if (miss) { api.bad(T(DRT.partMiss, { k: miss }), 'drillPart'); return; } st.stage = 2; snd('ok'); draw(); };
      $$('[data-arr]', box).forEach((b) => b.onclick = () => { const [k, n] = b.dataset.arr.split('|'); st.arr[k] = +n; draw(); });
      const ck = $('#chk', box); if (ck) ck.onclick = () => { if (st.found.some((k) => st.arr[k] !== DR.arr3(k.split(',').map(Number)))) { api.bad(T(DRT.arrWrong), 'drillArr'); return; } st.stage = 3; snd('ok'); draw(); };
      if (st.stage === 3) numPad($('#np', box), 'num', (v) => { const tot = st.found.reduce((a, k) => a + DR.arr3(k.split(',').map(Number)), 0); if (v === tot) api.ok(); else api.bad(st.found.map((k) => st.arr[k]).join(' + ') + ' = ?', 'drillCalc'); }); };
    draw(); };
}
// 表作り: one row per count of the largest coin; the child fills in each row (0 if that row is impossible), then the total
function rowsTask(rows) {
  return (box, api) => { const st = api.state; if (!st.vals) st.vals = {}; let sel = rows.findIndex((_, i) => st.vals[i] !== rows[i].ways);
    const draw = () => { const all = rows.every((_, i) => st.vals[i] === rows[i].ways);
      box.innerHTML = `<div class="panel interact"><div class="tdesc">${T(DRT.rowAsk)}</div><div class="tw"><table class="qtable">${rows.map((r, i) => `<tr data-row="${i}" style="cursor:pointer;${sel === i ? 'outline:3px solid var(--sun)' : ''}"><td>${T(r.lab)}</td><td>${T(DRT.rest, { r: r.rest })}</td><td style="font-family:var(--f-display);font-weight:700;min-width:60px;background:${st.vals[i] === undefined ? 'var(--paper2)' : st.vals[i] === r.ways ? '#d8f3df' : '#ffd0d8'}">${st.vals[i] ?? '?'}</td></tr>`).join('')}</table></div>
        ${all ? `<div class="tdesc">${T(DRT.rowsDone)}</div>` : ''}<div id="np" style="width:100%"></div></div>`;
      $$('[data-row]', box).forEach((r) => r.onclick = () => { sel = +r.dataset.row; draw(); });
      if (all) numPad($('#np', box), 'num', (v) => { if (v === rows.reduce((a, r) => a + r.ways, 0)) api.ok(); else api.bad(rows.map((r) => r.ways).join(' + ') + ' = ?', 'drillCalc'); });
      else if (sel >= 0) numPad($('#np', box), 'num', (v) => { st.vals[sel] = v; if (v !== rows[sel].ways) { api.bad(T(DRT.rowWrong), 'drillRow'); } else snd('pop'); sel = rows.findIndex((_, i) => st.vals[i] !== rows[i].ways); draw(); }); };
    draw(); };
}
function coinRows(den, tot, mins, maxs) { // rows by the largest coin, from most to least
  const L = den.length - 1, rows = [];
  for (let k = Math.min(maxs[L], Math.floor(tot / den[L])); k >= mins[L]; k--) {
    const rest = tot - k * den[L], ways = DR.pay(den.slice(0, L), rest, mins.slice(0, L), maxs.slice(0, L)).length;
    rows.push({ lab: tx(`${den[L]}円が${k}まい`, `${k} × ${den[L]} yen`, `${den[L]}日元${k}枚`), rest, ways });
  }
  return rows;
}
