          mis: [M(Math.floor(N / (k + 1)), 'noPlusOne', tx(`${Math.floor(N / (k + 1))}票だと、A ${Math.floor(N / (k + 1))}・B ${N - 2 * Math.floor(N / (k + 1))}・C ${Math.floor(N / (k + 1))} のように、C とならぶことがあるよ。ならんだら かならず当選とはいえない。`, `With ${Math.floor(N / (k + 1))}, it could be A ${Math.floor(N / (k + 1))}, B ${N - 2 * Math.floor(N / (k + 1))}, C ${Math.floor(N / (k + 1))} — tied with C, so not a sure win.`, `${Math.floor(N / (k + 1))}票时，可能是A ${Math.floor(N / (k + 1))}、B ${N - 2 * Math.floor(N / (k + 1))}、C ${Math.floor(N / (k + 1))}，和C并列，不算一定当选。`)), M(Math.floor(N / 2) + 1, 'bySeats', tx('2人当選なので、3人に票が集まるときを考えよう。', 'Two win, so think of votes on 3 people.', '选2人，所以想票集中在3人身上。'))].filter((m) => m.v !== s),
