// sumo round robin of 5: count result tables meeting a condition (wins[], beat has 'i>j')
const DRX = { sumo: (cond) => { const games = []; for (let i = 0; i < 5; i++) for (let j = i + 1; j < 5; j++) games.push([i, j]); let n = 0;
  for (let m = 0; m < 1 << games.length; m++) { const w = [0, 0, 0, 0, 0], beat = new Set(); games.forEach(([i, j], g) => { const [a, b] = m >> g & 1 ? [j, i] : [i, j]; w[a]++; beat.add(a + '>' + b); }); if (cond(w, beat)) n++; } return n; } };
